const VUELTA = 4;
const ANTERIOR = "Herramientas 3";
// ===== Generado por calculo/exportar-n8n.js. No editar aquí: editar calculo/ y flujos/n8n/src/ =====
// Las reglas (semáforo, prioridad, señales, vacante) y sus umbrales viven en definiciones/reglas.yaml (D-23): aquí solo se aplican.
const ORDEN = { verde: 0, ambar: 1, rojo: 2 };

// ---------- Cálculo ----------
function prioridad(semaforo, criticidad, reglas) {
  const R = reglas.prioridad;
  const p = R.puntos_semaforo[semaforo] * R.puntos_criticidad[criticidad];
  return (R.niveles.find(n => p >= n.puntos_minimos) || { prioridad: '-' }).prioridad;
}

// Semáforo de una skill: la primera regla de reglas.yaml (semaforo) que se cumple
function colorSkill(n, objetivo, conBackup, reglas) {
  for (const r of reglas.semaforo) {
    const si = r.si || {};
    const minimo = si.cobertura_minima === 'objetivo' ? objetivo : si.cobertura_minima;
    if (minimo != null && n < minimo) continue;
    if (si.cobertura != null && n !== si.cobertura) continue;
    if (si.con_backup && !conBackup) continue;
    return r.color;
  }
  throw new Error('reglas.yaml: ninguna regla del semáforo se cumple (la última debería no tener condiciones)');
}

function calcular(datos) {
  const { funciones, empleados, skills, planes, catalogo, reglas } = datos;
  const R = reglas;
  const objetivoDefecto = funciones.defaults.cobertura_objetivo;
  const activos = new Map(empleados.filter(e => e.estado === 'activo').map(e => [e.id, e]));
  const nivel = new Map(); // "E007|gestion-claves" -> nivel validado
  for (const s of skills) if (activos.has(s.empleado_id) && s.nivel_validado) nivel.set(`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado);
  const nivelDe = (id, skill) => nivel.get(`${id}|${skill}`) || 0;
  const interes = id => (activos.get(id).skills_interes || '').split(';').filter(Boolean);
  const planesActivos = planes.filter(p => p.estado === 'activo' && activos.has(p.empleado_id));

  // 1. Cobertura y semáforo por skill y por función
  const resultado = funciones.funciones.map(f => {
    const objetivo = f.cobertura_objetivo || objetivoDefecto;
    const skillsF = f.skills_requeridas.map(({ skill, nivel: min }) => {
      const cubren = [...activos.keys()].filter(id => nivelDe(id, skill) >= min);
      const backups = planesActivos
        .filter(p => p.skill_id === skill && nivelDe(p.empleado_id, skill) === min - R.cobertura.backup_a_distancia)
        .map(p => p.empleado_id);
      const n = cubren.length;
      const semaforo = colorSkill(n, objetivo, backups.length > 0, R);
      return { skill, nivel_minimo: min, cobertura: n, personas: cubren, backups_en_desarrollo: backups, semaforo };
    });
    const peor = skillsF.reduce((a, b) => (ORDEN[b.semaforo] > ORDEN[a.semaforo] || (b.semaforo === a.semaforo && b.cobertura < a.cobertura) ? b : a));
    // Lente AI first (reglas-semaforo.md §7): en rojo con impacto IA alto no se forma un backup del proceso actual
    const respuesta = peor.semaforo === R.rediseno_ia.semaforo && f.impacto_ia === R.rediseno_ia.impacto_ia ? 'redisenar' : 'cubrir';
    return {
      id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, impacto_ia: f.impacto_ia, objetivo,
      cobertura: Math.min(...skillsF.map(s => s.cobertura)),
      semaforo: peor.semaforo, prioridad: prioridad(peor.semaforo, f.criticidad, R), respuesta, skills: skillsF,
    };
  });

  // 2. Key people: única cobertura de una skill en función crítica o importante
  const keyPeople = new Map();
  for (const f of resultado) {
    if (!R.cobertura.key_person.criticidades.includes(f.criticidad)) continue;
    for (const s of f.skills) if (s.cobertura === R.cobertura.key_person.cobertura) {
      const id = s.personas[0];
      if (!keyPeople.has(id)) keyPeople.set(id, []);
      keyPeople.get(id).push({ funcion: f.id, skill: s.skill, semaforo: f.semaforo });
    }
  }

  // 3. Candidatos a backup y formación para skills en rojo/ámbar
  for (const f of resultado) for (const s of f.skills) {
    if (s.semaforo === 'verde') continue;
    s.candidatos = [...activos.keys()]
      .filter(id => nivelDe(id, s.skill) === s.nivel_minimo - R.cobertura.backup_a_distancia && !s.backups_en_desarrollo.includes(id))
      .map(id => ({ id, nombre: activos.get(id).nombre, area: activos.get(id).area, con_interes: interes(id).includes(s.skill), es_key_person: keyPeople.has(id) }))
      .sort((a, b) => b.con_interes - a.con_interes || a.es_key_person - b.es_key_person);
    // Un mentoring interno necesita a alguien que ya cubra la skill: con cobertura 0 no se propone
    s.formacion = catalogo.filter(c => c.skill === s.skill && c.a === s.nivel_minimo && !(c.tipo === 'mentoring-interno' && s.cobertura === 0)).map(c => c.id);
  }

  // 4. Señales de rotación (solo key people y personas que cubren funciones en rojo/ámbar)
  const enRiesgo = new Set(keyPeople.keys());
  for (const f of resultado) if (f.semaforo !== 'verde') for (const s of f.skills) if (s.semaforo !== 'verde') s.personas.forEach(id => enRiesgo.add(id));
  const senales = [...enRiesgo].map(id => ({ id, nombre: activos.get(id).nombre, ...senalesRotacion(activos.get(id), datos) }));

  return {
    funciones: resultado,
    key_people: [...keyPeople].map(([id, funcs]) => {
      const e = activos.get(id);
      const areaDe = fid => resultado.find(f => f.id === fid).area;
      // Oculta: puesto junior/intermedio, o sostiene una función de otra área (reglas-semaforo.md §3)
      const oculta = R.cobertura.key_person_oculta.niveles_puesto.includes(e.nivel_puesto) || funcs.some(f => areaDe(f.funcion) !== e.area);
      return { id, nombre: e.nombre, area: e.area, rol: e.rol, nivel_puesto: e.nivel_puesto, oculta, funciones: funcs };
    }),
    senales_rotacion: senales,
    madurez_ia: madurezIa(datos),
  };
}

// Madurez IA por área: nivel medio validado de cada skill de IA (sin la skill = 0).
// Áreas con menos de 5 personas se agrupan en su división, como las encuestas; si aun así no llegan a 5,
// no se publican. Así no se puede deducir el nivel de nadie.
function madurezIa(datos) {
  const skillsIa = datos.taxonomia.skills.filter(s => s.tipo === 'ia').map(s => s.id);
  const activos = datos.empleados.filter(e => e.estado === 'activo');
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const grupos = new Map();
  const cuenta = activos.reduce((m, e) => ((m[e.area] = (m[e.area] || 0) + 1), m), {});
  for (const e of activos) {
    const seg = cuenta[e.area] >= datos.reglas.anonimato.n_minimo ? e.area : `${datos.areas[e.area]} (áreas pequeñas)`;
    if (!grupos.has(seg)) grupos.set(seg, []);
    grupos.get(seg).push(e.id);
  }
  const media = ids => Object.fromEntries(skillsIa.map(s => [s, +(ids.reduce((t, id) => t + (nivel.get(`${id}|${s}`) || 0), 0) / ids.length).toFixed(1)]));
  return [...grupos].filter(([, ids]) => ids.length >= datos.reglas.anonimato.n_minimo).map(([segmento, ids]) => {
    const m = media(ids);
    return { segmento, n: ids.length, ...m, indice: +(skillsIa.reduce((t, s) => t + m[s], 0) / skillsIa.length).toFixed(1) };
  }).sort((a, b) => b.indice - a.indice);
}

function climaDe(area, datos) {
  const enc = datos.encuesta;
  const fila = (tipo, seg) => enc.find(r => r.segmento_tipo === tipo && r.segmento === seg && r.publicable === 'si' && +r.n >= datos.reglas.anonimato.n_minimo);
  return fila('area', area) || fila('division', datos.areas[area]) || null;
}

function senalesRotacion(e, datos) {
  const banda = datos.bandas.find(b => b.banda_id === e.banda_id);
  const compa = +(e.salario_ficticio / banda.medio).toFixed(2);
  const media = +datos.encuesta.find(r => r.segmento_tipo === 'compania').engagement;
  const clima = climaDe(e.area, datos);
  const U = datos.reglas.senales_rotacion;
  const activas = [];
  if (compa < U.compa_ratio_menor_que) activas.push(`S1 compa-ratio ${compa}`);
  if (+e.meses_desde_ultima_revision > U.meses_sin_revision_mas_de) activas.push(`S2 ${e.meses_desde_ultima_revision} meses sin revisión`);
  if (clima && +clima.engagement < media) activas.push(`S3 clima ${clima.segmento} ${clima.engagement} < ${media}`);
  if (+e.ultima_evaluacion >= U.evaluacion_desde) activas.push(`S4 evaluación ${e.ultima_evaluacion}`);
  if (+e.meses_con_manager_actual <= U.meses_con_manager_hasta) activas.push(`S5 ${e.meses_con_manager_actual} meses con su manager`);
  const probabilidad = activas.length >= U.probabilidad.alta_desde ? 'alta' : activas.length >= U.probabilidad.media_desde ? 'media' : 'baja';
  return { compa_ratio: compa, senales: activas, probabilidad };
}

// ---------- Escenarios ----------
function simularBaja(datos, id) {
  return { ...datos, empleados: datos.empleados.map(e => (e.id === id ? { ...e, estado: 'baja' } : e)) };
}
function simularBackup(datos, empleado, skill, funcion) {
  const plan = { plan_id: 'SIM', empleado_id: empleado, skill_id: skill, funcion_id: funcion || '', estado: 'activo' };
  return { ...datos, planes: [...datos.planes, plan] };
}

// ---------- Vacante y movilidad interna (reglas-semaforo.md §9) ----------
// Perfil del puesto que deja una persona: las skills que cubría en alguna función, con el nivel mínimo más alto
// que le pedían, y liderazgo si tenía equipo. Candidatos internos: quien cumple al menos la mitad del perfil.
function vacante(datos, id, despues = calcular(simularBaja(datos, id))) {
  const sale = datos.empleados.find(e => e.id === id);
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const niv = (e, skill) => nivel.get(`${e}|${skill}`) || 0;
  const req = new Map();
  for (const f of datos.funciones.funciones) for (const s of f.skills_requeridas)
    if (niv(id, s.skill) >= s.nivel && (!req.has(s.skill) || s.nivel > req.get(s.skill).nivel)) req.set(s.skill, { skill: s.skill, nivel: s.nivel, funcion: f.id });
  const equipo = datos.empleados.filter(e => e.manager_id === id && e.estado === 'activo').map(e => e.id);
  if (equipo.length) req.set('liderazgo', { skill: 'liderazgo', nivel: datos.reglas.vacante.nivel_liderazgo, funcion: '' });
  const perfil = [...req.values()];

  const cobertura = skill => datos.empleados.filter(e => e.estado === 'activo' && e.id !== id && niv(e.id, skill) >= (req.get(skill)?.nivel || 1)).length;
  const keyPeople = new Map(despues.key_people.map(k => [k.id, k.funciones.map(f => f.funcion)]));
  const candidatos = datos.empleados.filter(e => e.estado === 'activo' && e.id !== id).map(e => {
    const brechas = perfil.filter(p => niv(e.id, p.skill) < p.nivel).map(p => ({
      skill: p.skill, tiene: niv(e.id, p.skill), necesita: p.nivel, funcion: p.funcion,
      formacion: datos.catalogo.filter(c => c.skill === p.skill && c.de === niv(e.id, p.skill) && c.a === p.nivel
        && !(c.tipo === 'mentoring-interno' && cobertura(p.skill) === 0)).map(c => c.id),
    }));
    return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, cumple: perfil.length - brechas.length, de: perfil.length, brechas, key_person_en: keyPeople.get(e.id) || [] };
  }).filter(c => c.cumple >= Math.ceil(c.de * datos.reglas.vacante.cumple_minimo))
    .sort((a, b) => b.cumple - a.cumple || a.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0) - b.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0))
    .slice(0, datos.reglas.vacante.candidatos_max);
  return { id, nombre: sale.nombre, rol: sale.rol, area: sale.area, equipo: equipo.length, perfil, candidatos };
}

// Aprobar la opción interna: el candidato asume el puesto (rol, nivel, manager), el equipo pasa a depender de él
// y se abre un plan por cada brecha de un nivel que tenga formación en el catálogo. Devuelve filas nuevas, no escribe nada.
function aplicarMovilidad(empleados, vac, candidatoId, fecha, origen) {
  const sale = empleados.find(e => e.id === vac.id);
  const nuevos = empleados.map(e =>
    e.id === candidatoId ? { ...e, rol: sale.rol, nivel_puesto: sale.nivel_puesto, manager_id: sale.manager_id, meses_con_manager_actual: '0' }
      : e.manager_id === vac.id && e.estado === 'activo' ? { ...e, manager_id: candidatoId, meses_con_manager_actual: '0' } : e);
  const c = vac.candidatos.find(x => x.id === candidatoId);
  const planes = c.brechas.filter(b => b.necesita - b.tiene === 1 && b.formacion.length).map(b => ({
    empleado_id: candidatoId, skill_id: b.skill, nivel_objetivo: b.necesita, funcion_id: b.funcion, formacion_id: b.formacion[0],
    fecha_inicio: fecha, fecha_objetivo: '', estado: 'activo', origen,
  }));
  return { empleados: nuevos, planes };
}

// Compara con una foto anterior: funciones que empeoran o mejoran
function comparar(antes, despues) {
  const previo = new Map(antes.funciones.map(f => [f.id, f]));
  return despues.funciones.flatMap(f => {
    const a = previo.get(f.id);
    if (!a) return [];
    // Cambio de color, o cambio de cobertura sin cambiar de color fuera del verde
    const d = ORDEN[f.semaforo] - ORDEN[a.semaforo] || (f.semaforo !== 'verde' ? a.cobertura - f.cobertura : 0);
    if (!d) return [];
    return [{ id: f.id, nombre: f.nombre, cambio: d > 0 ? 'empeora' : 'mejora', de: a.semaforo, a: f.semaforo, cobertura_antes: a.cobertura, cobertura_despues: f.cobertura }];
  });
}


// Propuesta de acciones (pasos 4-5): contexto para Claude y propuesta por reglas si no hay IA.
// Sin dependencias: lo usan la demo local (demo.js) y el nodo de código de n8n (exportar-n8n.js).

function contexto(r, cambios, evento, vac, datos) {
  const ids = cambios.filter(c => c.cambio === 'empeora').map(c => c.id);
  const afectadas = r.funciones.filter(x => ids.includes(x.id));
  const implicadas = new Set(afectadas.flatMap(x => x.skills.filter(s => s.semaforo !== 'verde').flatMap(s => s.personas)));
  const formaciones = new Set(afectadas.flatMap(x => x.skills.flatMap(s => s.formacion || [])));
  // Si alguna función se rediseña con IA, la recualificación sale de las formaciones de IA del catálogo
  if (afectadas.some(x => x.respuesta === 'redisenar')) datos.catalogo.filter(c => c.skill.startsWith('ia-')).forEach(c => formaciones.add(c.id));
  if (vac) {
    // Lente AI first: una skill del puesto que solo sostiene funciones a rediseñar no se cubre tal cual (ni dentro ni fuera)
    vac.perfil.forEach(p => { p.redisenar = !!p.funcion && r.funciones.find(f => f.id === p.funcion)?.respuesta === 'redisenar'; });
    vac.candidatos.forEach(c => { implicadas.add(c.id); c.brechas.forEach(b => b.formacion.forEach(x => formaciones.add(x))); });
    // Solo People: compa-ratio del candidato frente a la banda del puesto que asumiría
    const banda = datos.bandas.find(b => b.banda_id === datos.empleados.find(e => e.id === vac.id).banda_id);
    vac.candidatos.forEach(c => { c.compa_en_puesto = +(datos.empleados.find(e => e.id === c.id).salario_ficticio / banda.medio).toFixed(2); c.banda_puesto = banda.banda_id; });
  }
  return {
    evento, cambios, funciones_afectadas: afectadas, key_people: r.key_people, vacante: vac,
    senales: r.senales_rotacion.filter(s => implicadas.has(s.id)),
    catalogo: datos.catalogo.filter(c => formaciones.has(c.id)),
  };
}

// Decisión de cubrir el puesto: dos opciones excluyentes con el mismo grupo (A fuera, B el mejor candidato interno)
function opcionesVacante(ctx) {
  const v = ctx.vacante;
  if (!v || !v.perfil.some(p => p.skill !== 'liderazgo' && !p.redisenar)) return [];
  const grupo = `VAC-${v.id}`;
  const prioridad = ctx.funciones_afectadas.map(x => x.prioridad).sort()[0] || 'P1';
  const ops = [{ prioridad, funcion_id: '', tipo: 'contratar', grupo, accion: `Opción A · Buscar fuera: ${v.rol} (${v.perfil.filter(p => !p.redisenar).map(p => `${p.skill} ${p.nivel}`).join(', ')})`, empleado_id: '', skill_id: '', formacion_id: '',
    por_que: v.candidatos.length ? 'Nadie dentro cumple el perfil completo.' : 'Ningún candidato interno cumple la mitad del perfil.',
    riesgo_si_no: `Proceso de 2-3 meses; mientras tanto, ${v.equipo ? `${v.equipo} personas sin responsable` : 'sus funciones dependen de quien quede'}.` }];
  const c = v.candidatos[0];
  if (c) {
    const conForm = c.brechas.find(b => b.formacion.length);
    ops.push({ prioridad, funcion_id: c.brechas.find(b => b.funcion)?.funcion || '', tipo: 'movilidad', grupo, accion: `Opción B · Mover a ${c.nombre} (${c.rol}) a ${v.rol}`, empleado_id: c.id, skill_id: conForm?.skill || '', formacion_id: conForm?.formacion[0] || '',
      por_que: `Cumple ${c.cumple} de ${c.de} skills del puesto. Le falta: ${c.brechas.map(b => `${b.skill} ${b.tiene} → ${b.necesita}${b.formacion.length ? ` (${b.formacion[0]})` : ' (sin formación en el catálogo)'}`).join('; ')}.`,
      riesgo_si_no: c.key_person_en.length ? `Coste organizativo: ya es la única cobertura de ${c.key_person_en.join(', ')}; asumir el puesto concentra el riesgo en una persona.` : 'Coste organizativo: su puesto actual queda por cubrir.' });
  }
  return ops;
}

function propuestaPorReglas(ctx) {
  const acciones = opcionesVacante(ctx);
  const enVacante = skill => ctx.vacante?.perfil.some(p => p.skill === skill);
  for (const fn of ctx.funciones_afectadas) for (const s of fn.skills.filter(x => x.semaforo !== 'verde')) {
    const cand = (s.candidatos || []).find(c => !c.es_key_person);
    const form = ctx.catalogo.find(c => c.skill === s.skill);
    if (fn.respuesta === 'redisenar') {
      // Lente AI first: no se forma a nadie en el proceso actual; se rediseña y se recualifica
      const formIa = ctx.catalogo.find(c => c.skill === 'ia-automatizacion' && c.de === 1);
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'rediseno', accion: `Rediseñar ${fn.nombre} con IA y automatización${cand ? ` y recualificar a ${cand.nombre}` : ''}`, empleado_id: cand?.id || '', skill_id: 'ia-automatizacion', formacion_id: formIa?.id || '', por_que: `Cobertura ${s.cobertura} en ${s.skill} e impacto IA alto: formar un backup en el proceso actual es invertir en un proceso que va a cambiar.${cand?.con_interes ? ` ${cand.nombre} tiene interés declarado.` : ''}`, riesgo_si_no: `${fn.nombre} sigue dependiendo de ${s.cobertura} persona(s) y de un proceso manual.` });
      if (s.cobertura === 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'redistribuir', accion: `Cubrir ${fn.nombre} con apoyo temporal mientras dura el rediseño`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: 'Nadie cubre la skill hoy.', riesgo_si_no: 'La próxima entrega queda sin responsable.' });
    }
    else if (cand && s.cobertura > 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'backup', accion: `Plan de backup: ${cand.nombre} en ${s.skill} (${s.nivel_minimo - 1} → ${s.nivel_minimo})`, empleado_id: cand.id, skill_id: s.skill, formacion_id: form?.id || '', por_que: `Cobertura ${s.cobertura}. ${cand.nombre} está a un nivel${cand.con_interes ? ' y tiene interés declarado' : ''}.`, riesgo_si_no: `La función ${fn.nombre} depende de ${s.cobertura} persona.` });
    else if (enVacante(s.skill)) { /* la cubre la decisión de la vacante (opciones A/B) */ }
    else acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'contratar', accion: `Abrir vacante con ${s.skill} nivel ${s.nivel_minimo}`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: `Cobertura ${s.cobertura} y ningún candidato interno llega a tiempo.`, riesgo_si_no: `${fn.nombre} queda sin nadie que pueda sostenerla.` });
    if (s.cobertura === 1) {
      const kp = s.personas[0];
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'retencion', accion: `Conversación de permanencia con ${ctx.key_people.find(k => k.id === kp)?.nombre || kp}`, empleado_id: kp, skill_id: s.skill, formacion_id: '', por_que: 'Es la única cobertura de la skill.', riesgo_si_no: 'Una segunda salida deja la función sin cobertura.' });
    }
  }
  const n = ctx.cambios.filter(c => c.cambio === 'empeora').length;
  const nOpciones = acciones.filter(a => a.grupo).length;
  const v = nOpciones ? ctx.vacante : null, c = nOpciones > 1 ? v.candidatos[0] : null;
  const resumen = v
    ? `${ctx.evento}: ${n} función(es) empeoran. Primera decisión: cómo cubrir el puesto de ${v.rol}, buscando fuera (A)${c ? ` o moviendo a ${c.nombre} (B)` : ''}. Además se proponen ${acciones.length - nOpciones} acción(es) para reducir el riesgo mientras tanto. Todo queda pendiente de aprobación por People.`
    : `${ctx.evento}: ${n} función(es) empeoran. Se proponen ${acciones.length} acciones para su aprobación por People.`;
  const sen = c && ctx.senales.find(s => s.id === c.id);
  const detalle = c ? `${c.nombre}: probabilidad ${sen?.probabilidad || 'baja'} (${sen?.senales.join('; ') || 'sin señales'}). Si asume el puesto con su salario actual, su compa-ratio en la banda ${c.banda_puesto} sería ${c.compa_en_puesto}: la opción B exige revisar condiciones.` : '';
  return { acciones, resumen_direccion: resumen, detalle_people: detalle, observaciones: 'Propuesta generada por reglas (sin IA).' };
}

// Mensaje de usuario para prompts/proponer-acciones.md (mismo orden que la sección ## User del prompt)
function mensajeClaude(ctx) {
  const j = v => JSON.stringify(v, null, 1);
  return `Evento: ${ctx.evento}

Cambios en el mapa:
${j(ctx.cambios)}

Funciones afectadas (detalle del cálculo):
${j(ctx.funciones_afectadas)}

Key people tras el cambio:
${j(ctx.key_people)}

Señales de rotación (solo personas implicadas, confidencial People):
${j(ctx.senales)}

Vacante (puesto que deja la persona, si aplica):
${j(ctx.vacante)}

Formaciones disponibles:
${j(ctx.catalogo)}`;
}


// Filas de las hojas calculadas del Sheet (cobertura, key-people, histórico, alertas).
// Sin dependencias: lo usan exportar-sheets.js y los nodos de código de n8n (exportar-n8n.js).

const COLS = {
  cobertura: ['funcion_id', 'area', 'nombre', 'criticidad', 'semaforo', 'icono', 'prioridad', 'cobertura', 'objetivo', 'skill_mas_debil', 'cubren', 'backup_en_desarrollo', 'candidatos_con_interes', 'impacto_ia', 'respuesta'],
  keyPeople: ['empleado_id', 'nombre', 'area', 'rol', 'oculta', 'funciones', 'skills'],
  historico: ['fecha', 'funcion_id', 'semaforo', 'cobertura', 'prioridad', 'evento'],
  bandeja: ['fecha', 'asunto', 'html'], // copia de cada email que envía el sistema: el panel la enseña sin depender de un buzón (D-22)
  alertas: ['alerta_id', 'fecha', 'evento', 'funcion_id', 'prioridad', 'cambio', 'tipo_accion', 'accion', 'empleado_id', 'skill_id', 'formacion_id', 'por_que', 'riesgo_si_no', 'decision', 'decidido_por', 'fecha_decision', 'grupo'],
};
const ICONO = { verde: '🟢', ambar: '🟡', rojo: '🔴' };

function filasCobertura(r, nombre) {
  return r.funciones.map(f => {
    const s = f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a));
    const debiles = f.skills.filter(x => x.semaforo !== 'verde');
    return [f.id, f.area, f.nombre, f.criticidad, f.semaforo, ICONO[f.semaforo], f.prioridad, f.cobertura, f.objetivo, s.skill,
      s.personas.map(nombre).join('; '),
      debiles.flatMap(x => x.backups_en_desarrollo).map(nombre).join('; '),
      debiles.flatMap(x => (x.candidatos || []).filter(c => c.con_interes).map(c => c.nombre)).join('; '),
      f.impacto_ia, f.respuesta === 'redisenar' ? 'rediseñar con IA' : 'cubrir'];
  });
}

function filasKeyPeople(r) {
  return r.key_people.map(k => [k.id, k.nombre, k.area, k.rol, k.oculta ? 'si' : 'no',
    k.funciones.map(f => f.funcion).join('; '), k.funciones.map(f => f.skill).join('; ')]);
}

function filasHistorico(r, fecha, evento) {
  return r.funciones.map(f => [fecha, f.id, f.semaforo, f.cobertura, f.prioridad, evento]);
}


// Automatizaciones con calendario (D-21): seguimiento de planes de backup y centinela de riesgo. No son agentes: aplican reglas.
// Implementa definiciones/reglas-agentes.md con los umbrales de definiciones/reglas.yaml (automatizaciones). Deterministas: deciden CUÁNDO actuar y QUÉ detectar; nunca deciden sobre una persona.
// Sin dependencias: lo usan la demo local (demo.js), el vídeo (exportar-video.js) y los nodos de código de n8n (exportar-n8n.js).

// Umbrales con nombres cortos, leídos de reglas.yaml (automatizaciones): seguimiento y centinela
const umbralesAutomatizaciones = reglas => ({
  diasEntreAvisos: reglas.automatizaciones.seguimiento.dias_entre_avisos,
  avisosAntesDeEscalar: reglas.automatizaciones.seguimiento.avisos_antes_de_escalar,
  mesesValidacion: reglas.automatizaciones.centinela.meses_validacion,
  diasDecisionPendiente: reglas.automatizaciones.centinela.dias_decision_pendiente,
});

const dias = (desde, hasta) => Math.round((Date.parse(hasta) - Date.parse(desde)) / 864e5);
const sumarDias = (fecha, n) => new Date(Date.parse(fecha) + n * 864e5).toISOString().slice(0, 10);
const fechaValida = f => /^\d{4}-\d{2}-\d{2}$/.test(String(f || '')) && !isNaN(Date.parse(f));

// Fecha en que toca comprobar un plan: la objetivo si la tiene; si no, el inicio más la duración de su formación
function fechaRevision(plan, catalogo) {
  if (fechaValida(plan.fecha_objetivo)) return plan.fecha_objetivo;
  const f = catalogo.find(c => c.id === plan.formacion_id);
  return fechaValida(plan.fecha_inicio) && f ? sumarDias(plan.fecha_inicio, f.semanas * 7) : '';
}

// ---------- Seguimiento de planes ----------
// Para cada plan activo que ha llegado a su fecha: avisa al manager, le recuerda cada 7 días y, tras 2 avisos, escala a People.
// Devuelve las acciones; no escribe nada. avisos y ultimo_aviso viven en la hoja planes-backup.
function seguimientoPlanes(datos, hoy) {
  const U = umbralesAutomatizaciones(datos.reglas);
  const persona = id => datos.empleados.find(e => e.id === id);
  const acciones = [];
  for (const p of datos.planes.filter(x => x.estado === 'activo')) {
    const revision = fechaRevision(p, datos.catalogo);
    if (!revision || hoy < revision) continue; // aún en curso
    const avisos = +p.avisos || 0;
    if (avisos > U.avisosAntesDeEscalar) continue; // ya escalado: lo lleva People
    if (avisos && fechaValida(p.ultimo_aviso) && dias(p.ultimo_aviso, hoy) < U.diasEntreAvisos) continue; // avisado hace poco
    const e = persona(p.empleado_id);
    if (!e || e.estado !== 'activo') continue;
    const m = persona(e.manager_id);
    const sinManager = !m || m.estado !== 'activo'; // p. ej. su manager se ha ido: no hay a quién avisar, va directo a People
    const nivel = datos.skills.find(s => s.empleado_id === e.id && s.skill_id === p.skill_id)?.nivel_validado || 0;
    acciones.push({
      tipo: sinManager || avisos >= U.avisosAntesDeEscalar ? 'escalar' : avisos ? 'recordatorio' : 'aviso', sin_manager: sinManager,
      plan_id: p.plan_id, funcion_id: p.funcion_id, skill_id: p.skill_id, nivel_actual: +nivel, nivel_objetivo: +p.nivel_objetivo, formacion_id: p.formacion_id,
      empleado: { id: e.id, nombre: e.nombre }, manager: m ? { id: m.id, nombre: m.nombre } : null,
      fecha_revision: revision, dias_desde_revision: dias(revision, hoy), avisos: sinManager ? U.avisosAntesDeEscalar + 1 : avisos + 1,
      motivo: sinManager ? `${e.nombre} no tiene un manager activo que pueda validar${m ? ` (${m.nombre} ya no está)` : ''}`
        : `${m.nombre} ha recibido ${avisos} avisos y no ha validado el nivel`,
    });
  }
  return acciones;
}

// ---------- Centinela de riesgo ----------
// Revisión programada: qué está frágil y desde cuándo, qué se ha degradado sin que nadie lo avise y qué está pendiente.
// r = calcular(datos); cambios = comparar(foto anterior, r); historico y alertas = filas de sus hojas.
function vigilar(datos, r, cambios, historico, alertas, hoy) {
  const U = umbralesAutomatizaciones(datos.reglas);
  const nombre = id => datos.empleados.find(e => e.id === id)?.nombre || id;
  // Desde cuándo está cada función en su color actual (racha en el histórico)
  const desde = f => {
    const h = historico.filter(x => x.funcion_id === f.id).sort((a, b) => (a.fecha < b.fecha ? -1 : 1));
    let d = '';
    for (const x of h) if (x.semaforo !== f.semaforo) d = ''; else if (!d) d = x.fecha;
    return d;
  };
  const fragiles = r.funciones.filter(f => f.prioridad === 'P1' || f.prioridad === 'P2').map(f => {
    const d = desde(f);
    return { id: f.id, nombre: f.nombre, area: f.area, semaforo: f.semaforo, prioridad: f.prioridad, cobertura: f.cobertura, objetivo: f.objetivo, desde: d, dias: d ? dias(d, hoy) : null,
      cubren: f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a)).personas.map(nombre) };
  });
  // Validaciones caducadas que sostienen funciones críticas o importantes al límite de su cobertura
  const limite = sumarDias(hoy, -Math.round(U.mesesValidacion * 30.44));
  const caducadas = [];
  for (const f of r.funciones.filter(x => x.criticidad !== 'soporte')) for (const s of f.skills.filter(x => x.cobertura <= f.objetivo)) for (const id of s.personas) {
    const v = datos.skills.find(x => x.empleado_id === id && x.skill_id === s.skill);
    if (v && fechaValida(v.fecha) && v.fecha < limite) caducadas.push({ funcion_id: f.id, skill: s.skill, empleado: nombre(id), validado_por: v.validado_por, fecha: v.fecha, meses: Math.floor(dias(v.fecha, hoy) / 30.44) });
  }
  const planes = datos.planes.filter(p => p.estado === 'activo').map(p => {
    const rev = fechaRevision(p, datos.catalogo);
    return { plan_id: p.plan_id, empleado: nombre(p.empleado_id), skill: p.skill_id, funcion_id: p.funcion_id, formacion_id: p.formacion_id, fecha_revision: rev,
      estado: rev && hoy >= rev ? 'toca validar' : 'en curso', avisos: +p.avisos || 0 };
  });
  const pendientes = alertas.filter(a => a.decision === 'pendiente' && fechaValida(a.fecha) && dias(a.fecha, hoy) >= U.diasDecisionPendiente)
    .map(a => ({ alerta_id: a.alerta_id, accion: a.accion, prioridad: a.prioridad, fecha: a.fecha, dias: dias(a.fecha, hoy) }));
  // Solo People: key people con señales de rotación (nunca va al informe de dirección)
  const kp = new Set(r.key_people.map(k => k.id));
  const senales = r.senales_rotacion.filter(s => kp.has(s.id) && s.probabilidad !== 'baja');
  const cuenta = r.funciones.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), { rojo: 0, ambar: 0, verde: 0 });
  // A dirección solo le llega "en seguimiento por People", sin el porqué (prompts/informe-direccion.md, regla 3)
  return { fecha: hoy, umbrales: U, cuenta, cambios, fragiles, key_people: r.key_people.map(k => ({ nombre: k.nombre, rol: k.rol, oculta: k.oculta, funciones: k.funciones.map(f => f.funcion), seguimiento: senales.some(s => s.id === k.id) })),
    caducadas, planes, pendientes, senales };
}

// Mensaje para Claude (prompts/informe-direccion.md): solo datos agregados y organizativos, sin señales ni salarios
function mensajeInforme(h, user) {
  const t = {
    fecha: h.fecha,
    mapa: [`Rojo ${h.cuenta.rojo} · ámbar ${h.cuenta.ambar} · verde ${h.cuenta.verde}`, ...h.fragiles.map(f => `${f.id} ${f.nombre} (${f.area}): ${f.semaforo} ${f.prioridad}, cobertura ${f.cobertura}/${f.objetivo}${f.dias != null ? `, en ${f.semaforo} desde ${f.desde} (${f.dias} días)` : ''}`)].join('\n'),
    key_people: h.key_people.map(k => `${k.nombre} · ${k.rol} · ${k.funciones.join(', ')}${k.oculta ? ' · oculta' : ''}${k.seguimiento ? ' · en seguimiento por People' : ''}`).join('\n'),
    cambios_mes: h.cambios.length ? h.cambios.map(c => `${c.id} ${c.nombre}: ${c.de} → ${c.a} (${c.cambio})`).join('\n') : 'Sin cambios respecto al último recálculo.',
    planes_backup: h.planes.map(p => `${p.plan_id} ${p.empleado} · ${p.skill} (${p.funcion_id}) · revisión ${p.fecha_revision || 'sin fecha'} · ${p.estado}`).join('\n') || 'Ninguno.',
    alertas_mes: [...h.pendientes.map(a => `${a.alerta_id} ${a.accion}: pendiente desde hace ${a.dias} días`),
      ...(h.caducadas.length ? [`${h.caducadas.length} validaciones de skills con más de ${h.umbrales.mesesValidacion} meses sostienen funciones al límite`] : [])].join('\n') || 'Ninguna.',
  };
  return user.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in t ? t[k] : m));
}

// Informe por reglas, con las secciones del prompt: si Claude no responde, el informe sale igual
function informePorReglas(h) {
  const p1 = h.fragiles.filter(f => f.prioridad === 'P1');
  const lin = xs => xs.map(x => `- ${x}`).join('\n');
  return [
    '## En una frase',
    `${h.cuenta.rojo} funciones en rojo, ${h.cuenta.ambar} en ámbar y ${h.cuenta.verde} en verde${p1.length ? `; ${p1.length} de prioridad 1` : ''}.`,
    '## Dónde somos frágiles',
    lin(h.fragiles.map(f => `**${f.id} ${f.nombre}** (${f.area}): ${f.prioridad}, cobertura ${f.cobertura} de ${f.objetivo}${f.dias != null ? `, ${f.dias} días en ${f.semaforo}` : ''}${f.cubren.length ? `. Depende de: ${f.cubren.join(', ')}` : '. Hoy no la cubre nadie'}`)),
    '## Qué ha cambiado',
    h.cambios.length ? lin(h.cambios.map(c => `${c.id} ${c.nombre}: ${c.de} → ${c.a}`)) : 'Nada desde el último recálculo.',
    '## Dependencia de personas',
    lin(h.key_people.map(k => `${k.nombre} (${k.rol}): ${k.funciones.join(', ')}${k.oculta ? ' · **oculta**' : ''}${k.seguimiento ? ' · en seguimiento por People' : ''}`)),
    '## Qué estamos haciendo',
    h.planes.length ? lin(h.planes.map(p => `Plan ${p.plan_id}: ${p.empleado} en ${p.skill} (${p.funcion_id}), ${p.estado}${p.fecha_revision ? `, revisión ${p.fecha_revision}` : ''}`)) : 'Ningún plan activo.',
    '## Qué necesitamos de dirección',
    lin([
      ...p1.filter(f => !f.cubren.length).map(f => `Decidir cómo cubrir **${f.id}**: hoy no la sabe hacer nadie (formar fuera, contratar o apoyo externo).`),
      ...h.pendientes.slice(0, 2).map(a => `Desbloquear ${a.alerta_id} (${a.accion}): ${a.dias} días sin decisión.`),
      ...(h.caducadas.length ? [`Pedir a los managers que revaliden ${h.caducadas.length} skills con más de ${h.umbrales.mesesValidacion} meses: el mapa vale lo que valga la validación.`] : []),
    ].slice(0, 3)),
  ].join('\n\n');
}

// Markdown sencillo (títulos, listas, negrita) → HTML de email
function mdAHtml(md) {
  const escapar = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const inline = s => escapar(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  const out = []; let lista = false;
  for (const l of String(md).replace(/\r/g, '').split('\n')) {
    const li = l.match(/^\s*(?:[-*]|\d+\.)\s+(.*)/);
    if (li) { if (!lista) { out.push('<ul>'); lista = true; } out.push(`<li>${inline(li[1])}</li>`); continue; }
    if (lista) { out.push('</ul>'); lista = false; }
    const t = l.match(/^(#{1,4})\s+(.*)/);
    if (t) out.push(`<h${Math.min(t[1].length + 2, 5)}>${inline(t[2])}</h${Math.min(t[1].length + 2, 5)}>`);
    else if (l.trim()) out.push(`<p>${inline(l)}</p>`);
  }
  if (lista) out.push('</ul>');
  return out.join('\n');
}


// Herramientas del Asistente de People (D-25): lo que un agente con Claude puede consultar para responder a People.
// El modelo decide qué herramienta usar y en qué orden; las cifras las calcula siempre el motor (calcular, comparar, vacante).
// Solo lectura: ninguna herramienta escribe. Privacidad por construcción: ninguna devuelve salarios, bandas, evaluaciones
// ni señales de rotación (para eso no hay herramienta, y el prompt manda negarse).
// Sin dependencias: recibe calcular, comparar y vacante como parámetro, para servir igual en Node y en los nodos de n8n.

const HERRAMIENTAS = [
  { name: 'consultar_mapa', description: 'Estado actual del mapa de cobertura: cuántas funciones hay en rojo, ámbar y verde, cuáles están en riesgo (con su prioridad, cobertura y quién las sostiene) y quiénes son las key people.',
    input_schema: { type: 'object', properties: {} } },
  { name: 'buscar_persona', description: 'Busca personas por nombre o id (por ejemplo "Carmen" o "E011"). Devuelve rol, área, manager, skills validadas y las funciones en las que es key person. No incluye datos salariales ni de desempeño.',
    input_schema: { type: 'object', properties: { texto: { type: 'string', description: 'Nombre, apellido o id de la persona' } }, required: ['texto'] } },
  { name: 'simular_baja', description: 'Simula qué pasaría si una persona dejara la compañía, sin cambiar nada: qué funciones empeoran, quién pasa a ser key person y qué candidatos internos podrían cubrir su puesto, con sus brechas.',
    input_schema: { type: 'object', properties: { empleado_id: { type: 'string', description: 'Id de la persona, por ejemplo E011. Si solo tienes el nombre, usa antes buscar_persona.' } }, required: ['empleado_id'] } },
  { name: 'candidatos_para_funcion', description: 'Para una función (por ejemplo CUS-02), devuelve las skills que pide, quién la cubre hoy, las personas a un nivel de distancia (indicando si tienen interés declarado) y la formación del catálogo que cerraría la brecha.',
    input_schema: { type: 'object', properties: { funcion_id: { type: 'string', description: 'Id de la función, por ejemplo CUS-02' } }, required: ['funcion_id'] } },
  { name: 'madurez_ia', description: 'Madurez IA por área (media de uso diario, automatización y criterio), siempre agregada: no se publica ningún grupo de menos de 5 personas.',
    input_schema: { type: 'object', properties: {} } },
];

const normalizar = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

function ejecutarHerramienta(nombre, entrada, datos, motor) {
  const { calcular, comparar, vacante } = motor;
  const r = calcular(datos);
  const persona = id => datos.empleados.find(e => e.id === id);
  const nombreDe = id => persona(id)?.nombre || id;
  const skillNombre = id => datos.taxonomia.skills.find(s => s.id === id)?.nombre || id;
  const resumenFuncion = f => ({ id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, semaforo: f.semaforo, prioridad: f.prioridad,
    cobertura: f.cobertura, objetivo: f.objetivo, respuesta: f.respuesta === 'redisenar' ? 'rediseñar con IA' : 'cubrir',
    sostienen: f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a)).personas.map(nombreDe) });
  const keyPeople = res => res.key_people.map(k => ({ nombre: k.nombre, rol: k.rol, area: k.area, oculta: k.oculta, funciones: k.funciones.map(f => f.funcion) }));
  const cuenta = res => res.funciones.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), { rojo: 0, ambar: 0, verde: 0 });

  if (nombre === 'consultar_mapa') {
    return { mapa: cuenta(r), funciones_en_riesgo: r.funciones.filter(f => f.semaforo !== 'verde').map(resumenFuncion), key_people: keyPeople(r) };
  }
  if (nombre === 'buscar_persona') {
    const q = normalizar(entrada.texto);
    if (!q) return { error: 'Falta el texto a buscar' };
    const halladas = datos.empleados.filter(e => normalizar(e.id) === q || normalizar(e.nombre).includes(q)).slice(0, 5);
    if (!halladas.length) return { personas: [], nota: `No hay nadie que coincida con "${entrada.texto}"` };
    return { personas: halladas.map(e => {
      const kp = r.key_people.find(k => k.id === e.id);
      return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, estado: e.estado, manager: nombreDe(e.manager_id),
        skills_validadas: datos.skills.filter(s => s.empleado_id === e.id && +s.nivel_validado > 0).map(s => ({ skill: skillNombre(s.skill_id), nivel: +s.nivel_validado })),
        key_person_en: kp ? kp.funciones.map(f => f.funcion) : [] };
    }) };
  }
  if (nombre === 'simular_baja') {
    const id = String(entrada.empleado_id || '').trim().toUpperCase();
    const e = persona(id);
    if (!e) return { error: `No existe ninguna persona con id ${id}. Usa buscar_persona.` };
    if (e.estado !== 'activo') return { error: `${e.nombre} ya no está activa: no se puede simular su baja.` };
    const vac = vacante(datos, id);
    const tras = calcular({ ...datos, empleados: datos.empleados.map(x => (x.id === id ? { ...x, estado: 'baja' } : x)) });
    const cambios = comparar(r, tras).map(c => ({ ...c, nombre: tras.funciones.find(f => f.id === c.id).nombre }));
    const antes = new Set(r.key_people.map(k => k.id));
    return {
      simulacion: `Baja de ${e.nombre} (${e.rol}). No se ha cambiado nada en el HRIS.`,
      funciones_que_empeoran: cambios.filter(c => c.cambio === 'empeora').map(c => ({ id: c.id, nombre: c.nombre, de: c.de, a: c.a, cobertura_antes: c.cobertura_antes, cobertura_despues: c.cobertura_despues })),
      mapa_antes: cuenta(r), mapa_despues: cuenta(tras),
      nuevas_key_people: keyPeople(tras).filter(k => !antes.has(tras.key_people.find(x => x.nombre === k.nombre).id)),
      puesto: { rol: vac.rol, equipo: vac.equipo, perfil: vac.perfil.map(p => ({ skill: skillNombre(p.skill), nivel: p.nivel })),
        candidatos_internos: vac.candidatos.map(c => ({ nombre: c.nombre, rol: c.rol, cumple: `${c.cumple} de ${c.de}`,
          brechas: c.brechas.map(b => ({ skill: skillNombre(b.skill), tiene: b.tiene, necesita: b.necesita, formacion: b.formacion })), ya_es_key_person_en: c.key_person_en })) },
    };
  }
  if (nombre === 'candidatos_para_funcion') {
    const fid = String(entrada.funcion_id || '').trim().toUpperCase();
    const f = r.funciones.find(x => x.id === fid);
    if (!f) return { error: `No existe la función ${fid}. Usa consultar_mapa para ver los ids.` };
    return { ...resumenFuncion(f), skills: f.skills.map(s => ({ skill: skillNombre(s.skill), nivel_minimo: s.nivel_minimo, cobertura: s.cobertura, semaforo: s.semaforo,
      cubren: s.personas.map(nombreDe), backups_en_desarrollo: s.backups_en_desarrollo.map(nombreDe),
      a_un_nivel: (s.candidatos || []).map(c => ({ nombre: c.nombre, area: c.area, con_interes: c.con_interes, ya_es_key_person: c.es_key_person })),
      formacion: (s.formacion || []).map(id => { const c = datos.catalogo.find(x => x.id === id); return { id, nombre: c.nombre, semanas: c.semanas }; }) })) };
  }
  if (nombre === 'madurez_ia') return { madurez_por_area: r.madurez_ia };
  return { error: `No existe la herramienta ${nombre}` };
}

// Una línea legible de lo que devolvió una herramienta, para enseñar cómo ha razonado el agente
function resumenResultado(nombre, res) {
  if (res.error) return res.error;
  if (nombre === 'consultar_mapa') return `Mapa ${res.mapa.rojo}·${res.mapa.ambar}·${res.mapa.verde}; ${res.funciones_en_riesgo.length} funciones en riesgo; ${res.key_people.length} key people`;
  if (nombre === 'buscar_persona') return res.personas.length ? res.personas.map(p => `${p.id} ${p.nombre} (${p.rol})`).join('; ') : res.nota;
  if (nombre === 'simular_baja') return `${res.funciones_que_empeoran.length} función(es) empeoran (${res.funciones_que_empeoran.map(f => `${f.id} ${f.de}→${f.a}`).join(', ') || 'ninguna'}); ${res.puesto.candidatos_internos.length} candidato(s) interno(s)`;
  if (nombre === 'candidatos_para_funcion') return `${res.id} ${res.semaforo} ${res.prioridad}; cobertura ${res.cobertura}/${res.objetivo}`;
  if (nombre === 'madurez_ia') return `${res.madurez_por_area.length} áreas publicadas`;
  return '';
}


// Utilidades de los nodos de código de n8n: leer el HRIS y preparar las filas a escribir.
// Los escenarios no hablan con Google Sheets: llaman al subworkflow HRIS (D-24), que lee y escribe las hojas.
// exportar-n8n.js las concatena con el motor (cobertura.js), la propuesta (propuesta.js) y las filas (hojas.js).

// Hojas del HRIS y el nodo que las lee dentro del subworkflow HRIS. bandas y encuesta no cambian en la demo: vienen de definiciones.json (repo).
const LECTURAS = { empleados: 'Leer empleados', 'skills-empleados': 'Leer skills', 'planes-backup': 'Leer planes', alertas: 'Leer alertas', cobertura: 'Leer cobertura', 'historico-semaforo': 'Leer histórico',
  'key-people': 'Leer key-people', bandeja: 'Leer bandeja' };
// Cómo escribe el HRIS cada hoja (operación escribir): actualizar por clave, añadir o actualizar por clave, añadir, o vaciar y volver a escribir
const ESCRITURAS = {
  empleados: { op: 'update', clave: 'id' },
  'skills-empleados': { op: 'update', clave: 'row_number' },
  'skills-empleados (nueva)': { op: 'append', hoja: 'skills-empleados' }, // una skill que la persona no tenía
  'planes-backup': { op: 'appendOrUpdate', clave: 'plan_id' },
  alertas: { op: 'appendOrUpdate', clave: 'alerta_id' },
  cobertura: { op: 'appendOrUpdate', clave: 'funcion_id' },
  'historico-semaforo': { op: 'append' },
  'key-people': { op: 'reemplazar' },
  bandeja: { op: 'append' },
};
const hoyISO = () => new Date().toISOString().slice(0, 10);
// Hojas que el reinicio (escenario 0) vuelve a cargar desde salidas/sheets/; alertas y bandeja se vacían sin más
const HOJAS_INICIALES = ['empleados', 'skills-empleados', 'planes-backup', 'cobertura', 'key-people', 'historico-semaforo'];
// Fecha de trabajo de las automatizaciones con calendario: la del formulario "Ejecutar ahora" ("+12 semanas" o una fecha exacta) o hoy
function fechaDe(cfg) {
  const f = String(cfg.fecha || '').trim();
  if (fechaValida(f)) return f;
  const s = String(cfg.cuando || '').match(/\+\s*(\d+)\s*semana/);
  return s ? sumarDias(hoyISO(), +s[1] * 7) : hoyISO();
}

// Lo que devuelve el nodo "Leer HRIS" → { hoja: { filas: [{ ...columnas, _fila }] } }. _fila es la fila real (row_number).
function tablas() {
  const crudo = $('Leer HRIS').first().json.tablas || {};
  const t = {};
  for (const hoja of Object.keys(LECTURAS)) {
    const items = crudo[hoja] || [];
    t[hoja] = { filas: items.filter(o => Object.keys(o).some(k => k !== 'row_number' && o[k] !== '' && o[k] != null)).map(o => {
      const f = { _fila: o.row_number };
      for (const [k, v] of Object.entries(o)) if (k !== 'row_number') f[k] = v == null ? '' : String(v);
      return f;
    }) };
  }
  return t;
}

// Enlace para ver el HRIS (en la demo, el Sheet): lo da el propio HRIS al leer
function enlaceHris() { try { return $('Leer HRIS').first().json.enlace || ''; } catch (err) { return ''; } }

function datosDesde(T, defs) {
  return {
    funciones: defs.funciones, taxonomia: defs.taxonomia, areas: defs.areas, catalogo: defs.catalogo,
    bandas: defs.bandas, encuesta: defs.encuesta, reglas: defs.reglas,
    empleados: T['empleados'].filas, skills: T['skills-empleados'].filas, planes: T['planes-backup'].filas,
  };
}

// Foto anterior = lo que muestra ahora la hoja cobertura (siempre refleja el último recálculo)
function fotoActual(T) {
  return { funciones: T['cobertura'].filas.map(x => ({ id: x.funcion_id, semaforo: x.semaforo, cobertura: +x.cobertura, nombre: x.nombre })) };
}

// ---------- Filas a escribir: cada una lleva _hoja para que el desvío la mande a su nodo ----------
const valor = v => (v == null ? '' : typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v) && !/^0\d/.test(v) ? +v : v);
const fila = (hoja, obj, columnas = Object.keys(obj).filter(k => !k.startsWith('_'))) =>
  ({ _hoja: hoja, ...Object.fromEntries(columnas.map(c => [c, valor(obj[c])])) });
const filasDe = (hoja, cols, arrays) => arrays.map(a => fila(hoja, Object.fromEntries(cols.map((c, i) => [c, a[i]]))));

// Mapa tras un recálculo: cobertura (por funcion_id), key-people (se vacía y se reescribe) y foto en el histórico
function filasMapa(r, datos, evento, fecha = hoyISO()) {
  const nombre = id => datos.empleados.find(e => e.id === id)?.nombre || id;
  return [
    ...filasDe('cobertura', COLS.cobertura, filasCobertura(r, nombre)),
    ...filasDe('key-people', COLS.keyPeople, filasKeyPeople(r)),
    ...filasDe('historico-semaforo', COLS.historico, filasHistorico(r, fecha, evento)),
  ];
}

// ---------- Email (HTML sencillo, se ve bien en Gmail) ----------
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = cuerpo => `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:680px">${cuerpo}<p style="color:#888;font-size:12px;margin-top:24px">Acme People OS · datos ficticios · generado automáticamente</p></div>`;
function listaCambios(cambios) {
  return `<ul>${cambios.map(c => `<li><b>${esc(c.id)}</b> ${esc(c.nombre)}: ${ICONO[c.de]} → ${ICONO[c.a]} (cobertura ${c.cobertura_antes} → ${c.cobertura_despues})</li>`).join('')}</ul>`;
}


// ===== Nodo =====
// Escenario 4 · nodo "Herramientas k" (D-25): una vuelta del bucle del agente.
// Lee la respuesta de Claude: si pide herramientas, las ejecuta con el motor (solo lectura), añade los resultados a la
// conversación y sigue; si ya ha respondido, termina. VUELTA y ANTERIOR los pone el generador (exportar-n8n.js).
const prev = $(ANTERIOR).first().json;
const res = $input.first().json || {};
const traza = [...prev.traza];
if (!Array.isArray(res.content)) {
  return [{ json: { ...prev, sigue: false, final: null, error: 'Claude no ha respondido (revisa la credencial Header Auth o el límite de gasto).', traza } }];
}
const texto = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
const usos = res.content.filter(b => b.type === 'tool_use');
if (res.stop_reason !== 'tool_use' || !usos.length) {
  return [{ json: { ...prev, sigue: false, final: texto, traza, body: null } }];
}
const defs = JSON.parse($('Leer definiciones').first().json.definiciones);
const datos = datosDesde(tablas(), defs);
const resultados = usos.map(u => {
  const r = ejecutarHerramienta(u.name, u.input || {}, datos, { calcular, comparar, vacante });
  traza.push({ vuelta: VUELTA, pensado: texto, herramienta: u.name, entrada: u.input || {}, resumen: resumenResultado(u.name, r) });
  return { type: 'tool_result', tool_use_id: u.id, content: JSON.stringify(r) };
});
const body = { ...prev.body, messages: [...prev.body.messages, { role: 'assistant', content: res.content }, { role: 'user', content: resultados }] };
return [{ json: { ...prev, sigue: true, body, traza } }];

// ===== Generado por calculo/exportar-n8n.js. No editar aquí: editar calculo/ y flujos/n8n/src/ =====
// Las reglas (semáforo, prioridad, señales, vacante) y sus umbrales viven en definiciones/reglas.yaml (D-23): aquí solo se aplican.
const ORDEN = { verde: 0, ambar: 1, rojo: 2 };

// ---------- Cálculo ----------
function prioridad(semaforo, criticidad, reglas) {
  const R = reglas.prioridad;
  const p = R.puntos_semaforo[semaforo] * R.puntos_criticidad[criticidad];
  return (R.niveles.find(n => p >= n.puntos_minimos) || { prioridad: '-' }).prioridad;
}

// Semáforo de una skill: la primera regla de reglas.yaml (semaforo) que se cumple
function colorSkill(n, objetivo, conBackup, reglas) {
  for (const r of reglas.semaforo) {
    const si = r.si || {};
    const minimo = si.cobertura_minima === 'objetivo' ? objetivo : si.cobertura_minima;
    if (minimo != null && n < minimo) continue;
    if (si.cobertura != null && n !== si.cobertura) continue;
    if (si.con_backup && !conBackup) continue;
    return r.color;
  }
  throw new Error('reglas.yaml: ninguna regla del semáforo se cumple (la última debería no tener condiciones)');
}

function calcular(datos) {
  const { funciones, empleados, skills, planes, catalogo, reglas } = datos;
  const R = reglas;
  const objetivoDefecto = funciones.defaults.cobertura_objetivo;
  const activos = new Map(empleados.filter(e => e.estado === 'activo').map(e => [e.id, e]));
  const nivel = new Map(); // "E007|gestion-claves" -> nivel validado
  for (const s of skills) if (activos.has(s.empleado_id) && s.nivel_validado) nivel.set(`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado);
  const nivelDe = (id, skill) => nivel.get(`${id}|${skill}`) || 0;
  const interes = id => (activos.get(id).skills_interes || '').split(';').filter(Boolean);
  const planesActivos = planes.filter(p => p.estado === 'activo' && activos.has(p.empleado_id));

  // 1. Cobertura y semáforo por skill y por función
  const resultado = funciones.funciones.map(f => {
    const objetivo = f.cobertura_objetivo || objetivoDefecto;
    const skillsF = f.skills_requeridas.map(({ skill, nivel: min }) => {
      const cubren = [...activos.keys()].filter(id => nivelDe(id, skill) >= min);
      const backups = planesActivos
        .filter(p => p.skill_id === skill && nivelDe(p.empleado_id, skill) === min - R.cobertura.backup_a_distancia)
        .map(p => p.empleado_id);
      const n = cubren.length;
      const semaforo = colorSkill(n, objetivo, backups.length > 0, R);
      return { skill, nivel_minimo: min, cobertura: n, personas: cubren, backups_en_desarrollo: backups, semaforo };
    });
    const peor = skillsF.reduce((a, b) => (ORDEN[b.semaforo] > ORDEN[a.semaforo] || (b.semaforo === a.semaforo && b.cobertura < a.cobertura) ? b : a));
    // Lente AI first (reglas-semaforo.md §7): en rojo con impacto IA alto no se forma un backup del proceso actual
    const respuesta = peor.semaforo === R.rediseno_ia.semaforo && f.impacto_ia === R.rediseno_ia.impacto_ia ? 'redisenar' : 'cubrir';
    return {
      id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, impacto_ia: f.impacto_ia, objetivo,
      cobertura: Math.min(...skillsF.map(s => s.cobertura)),
      semaforo: peor.semaforo, prioridad: prioridad(peor.semaforo, f.criticidad, R), respuesta, skills: skillsF,
    };
  });

  // 2. Key people: única cobertura de una skill en función crítica o importante
  const keyPeople = new Map();
  for (const f of resultado) {
    if (!R.cobertura.key_person.criticidades.includes(f.criticidad)) continue;
    for (const s of f.skills) if (s.cobertura === R.cobertura.key_person.cobertura) {
      const id = s.personas[0];
      if (!keyPeople.has(id)) keyPeople.set(id, []);
      keyPeople.get(id).push({ funcion: f.id, skill: s.skill, semaforo: f.semaforo });
    }
  }

  // 3. Candidatos a backup y formación para skills en rojo/ámbar
  for (const f of resultado) for (const s of f.skills) {
    if (s.semaforo === 'verde') continue;
    s.candidatos = [...activos.keys()]
      .filter(id => nivelDe(id, s.skill) === s.nivel_minimo - R.cobertura.backup_a_distancia && !s.backups_en_desarrollo.includes(id))
      .map(id => ({ id, nombre: activos.get(id).nombre, area: activos.get(id).area, con_interes: interes(id).includes(s.skill), es_key_person: keyPeople.has(id) }))
      .sort((a, b) => b.con_interes - a.con_interes || a.es_key_person - b.es_key_person);
    // Un mentoring interno necesita a alguien que ya cubra la skill: con cobertura 0 no se propone
    s.formacion = catalogo.filter(c => c.skill === s.skill && c.a === s.nivel_minimo && !(c.tipo === 'mentoring-interno' && s.cobertura === 0)).map(c => c.id);
  }

  // 4. Señales de rotación (solo key people y personas que cubren funciones en rojo/ámbar)
  const enRiesgo = new Set(keyPeople.keys());
  for (const f of resultado) if (f.semaforo !== 'verde') for (const s of f.skills) if (s.semaforo !== 'verde') s.personas.forEach(id => enRiesgo.add(id));
  const senales = [...enRiesgo].map(id => ({ id, nombre: activos.get(id).nombre, ...senalesRotacion(activos.get(id), datos) }));

  return {
    funciones: resultado,
    key_people: [...keyPeople].map(([id, funcs]) => {
      const e = activos.get(id);
      const areaDe = fid => resultado.find(f => f.id === fid).area;
      // Oculta: puesto junior/intermedio, o sostiene una función de otra área (reglas-semaforo.md §3)
      const oculta = R.cobertura.key_person_oculta.niveles_puesto.includes(e.nivel_puesto) || funcs.some(f => areaDe(f.funcion) !== e.area);
      return { id, nombre: e.nombre, area: e.area, rol: e.rol, nivel_puesto: e.nivel_puesto, oculta, funciones: funcs };
    }),
    senales_rotacion: senales,
    madurez_ia: madurezIa(datos),
  };
}

// Madurez IA por área: nivel medio validado de cada skill de IA (sin la skill = 0).
// Áreas con menos de 5 personas se agrupan en su división, como las encuestas; si aun así no llegan a 5,
// no se publican. Así no se puede deducir el nivel de nadie.
function madurezIa(datos) {
  const skillsIa = datos.taxonomia.skills.filter(s => s.tipo === 'ia').map(s => s.id);
  const activos = datos.empleados.filter(e => e.estado === 'activo');
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const grupos = new Map();
  const cuenta = activos.reduce((m, e) => ((m[e.area] = (m[e.area] || 0) + 1), m), {});
  for (const e of activos) {
    const seg = cuenta[e.area] >= datos.reglas.anonimato.n_minimo ? e.area : `${datos.areas[e.area]} (áreas pequeñas)`;
    if (!grupos.has(seg)) grupos.set(seg, []);
    grupos.get(seg).push(e.id);
  }
  const media = ids => Object.fromEntries(skillsIa.map(s => [s, +(ids.reduce((t, id) => t + (nivel.get(`${id}|${s}`) || 0), 0) / ids.length).toFixed(1)]));
  return [...grupos].filter(([, ids]) => ids.length >= datos.reglas.anonimato.n_minimo).map(([segmento, ids]) => {
    const m = media(ids);
    return { segmento, n: ids.length, ...m, indice: +(skillsIa.reduce((t, s) => t + m[s], 0) / skillsIa.length).toFixed(1) };
  }).sort((a, b) => b.indice - a.indice);
}

function climaDe(area, datos) {
  const enc = datos.encuesta;
  const fila = (tipo, seg) => enc.find(r => r.segmento_tipo === tipo && r.segmento === seg && r.publicable === 'si' && +r.n >= datos.reglas.anonimato.n_minimo);
  return fila('area', area) || fila('division', datos.areas[area]) || null;
}

function senalesRotacion(e, datos) {
  const banda = datos.bandas.find(b => b.banda_id === e.banda_id);
  const compa = +(e.salario_ficticio / banda.medio).toFixed(2);
  const media = +datos.encuesta.find(r => r.segmento_tipo === 'compania').engagement;
  const clima = climaDe(e.area, datos);
  const U = datos.reglas.senales_rotacion;
  const activas = [];
  if (compa < U.compa_ratio_menor_que) activas.push(`S1 compa-ratio ${compa}`);
  if (+e.meses_desde_ultima_revision > U.meses_sin_revision_mas_de) activas.push(`S2 ${e.meses_desde_ultima_revision} meses sin revisión`);
  if (clima && +clima.engagement < media) activas.push(`S3 clima ${clima.segmento} ${clima.engagement} < ${media}`);
  if (+e.ultima_evaluacion >= U.evaluacion_desde) activas.push(`S4 evaluación ${e.ultima_evaluacion}`);
  if (+e.meses_con_manager_actual <= U.meses_con_manager_hasta) activas.push(`S5 ${e.meses_con_manager_actual} meses con su manager`);
  const probabilidad = activas.length >= U.probabilidad.alta_desde ? 'alta' : activas.length >= U.probabilidad.media_desde ? 'media' : 'baja';
  return { compa_ratio: compa, senales: activas, probabilidad };
}

// ---------- Escenarios ----------
function simularBaja(datos, id) {
  return { ...datos, empleados: datos.empleados.map(e => (e.id === id ? { ...e, estado: 'baja' } : e)) };
}
function simularBackup(datos, empleado, skill, funcion) {
  const plan = { plan_id: 'SIM', empleado_id: empleado, skill_id: skill, funcion_id: funcion || '', estado: 'activo' };
  return { ...datos, planes: [...datos.planes, plan] };
}

// ---------- Vacante y movilidad interna (reglas-semaforo.md §9) ----------
// Perfil del puesto que deja una persona: las skills que cubría en alguna función, con el nivel mínimo más alto
// que le pedían, y liderazgo si tenía equipo. Candidatos internos: quien cumple al menos la mitad del perfil.
function vacante(datos, id, despues = calcular(simularBaja(datos, id))) {
  const sale = datos.empleados.find(e => e.id === id);
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const niv = (e, skill) => nivel.get(`${e}|${skill}`) || 0;
  const req = new Map();
  for (const f of datos.funciones.funciones) for (const s of f.skills_requeridas)
    if (niv(id, s.skill) >= s.nivel && (!req.has(s.skill) || s.nivel > req.get(s.skill).nivel)) req.set(s.skill, { skill: s.skill, nivel: s.nivel, funcion: f.id });
  const equipo = datos.empleados.filter(e => e.manager_id === id && e.estado === 'activo').map(e => e.id);
  if (equipo.length) req.set('liderazgo', { skill: 'liderazgo', nivel: datos.reglas.vacante.nivel_liderazgo, funcion: '' });
  const perfil = [...req.values()];

  const cobertura = skill => datos.empleados.filter(e => e.estado === 'activo' && e.id !== id && niv(e.id, skill) >= (req.get(skill)?.nivel || 1)).length;
  const keyPeople = new Map(despues.key_people.map(k => [k.id, k.funciones.map(f => f.funcion)]));
  const candidatos = datos.empleados.filter(e => e.estado === 'activo' && e.id !== id).map(e => {
    const brechas = perfil.filter(p => niv(e.id, p.skill) < p.nivel).map(p => ({
      skill: p.skill, tiene: niv(e.id, p.skill), necesita: p.nivel, funcion: p.funcion,
      formacion: datos.catalogo.filter(c => c.skill === p.skill && c.de === niv(e.id, p.skill) && c.a === p.nivel
        && !(c.tipo === 'mentoring-interno' && cobertura(p.skill) === 0)).map(c => c.id),
    }));
    return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, cumple: perfil.length - brechas.length, de: perfil.length, brechas, key_person_en: keyPeople.get(e.id) || [] };
  }).filter(c => c.cumple >= Math.ceil(c.de * datos.reglas.vacante.cumple_minimo))
    .sort((a, b) => b.cumple - a.cumple || a.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0) - b.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0))
    .slice(0, datos.reglas.vacante.candidatos_max);
  return { id, nombre: sale.nombre, rol: sale.rol, area: sale.area, equipo: equipo.length, perfil, candidatos };
}

// Aprobar la opción interna: el candidato asume el puesto (rol, nivel, manager), el equipo pasa a depender de él
// y se abre un plan por cada brecha de un nivel que tenga formación en el catálogo. Devuelve filas nuevas, no escribe nada.
function aplicarMovilidad(empleados, vac, candidatoId, fecha, origen) {
  const sale = empleados.find(e => e.id === vac.id);
  const nuevos = empleados.map(e =>
    e.id === candidatoId ? { ...e, rol: sale.rol, nivel_puesto: sale.nivel_puesto, manager_id: sale.manager_id, meses_con_manager_actual: '0' }
      : e.manager_id === vac.id && e.estado === 'activo' ? { ...e, manager_id: candidatoId, meses_con_manager_actual: '0' } : e);
  const c = vac.candidatos.find(x => x.id === candidatoId);
  const planes = c.brechas.filter(b => b.necesita - b.tiene === 1 && b.formacion.length).map(b => ({
    empleado_id: candidatoId, skill_id: b.skill, nivel_objetivo: b.necesita, funcion_id: b.funcion, formacion_id: b.formacion[0],
    fecha_inicio: fecha, fecha_objetivo: '', estado: 'activo', origen,
  }));
  return { empleados: nuevos, planes };
}

// Compara con una foto anterior: funciones que empeoran o mejoran
function comparar(antes, despues) {
  const previo = new Map(antes.funciones.map(f => [f.id, f]));
  return despues.funciones.flatMap(f => {
    const a = previo.get(f.id);
    if (!a) return [];
    // Cambio de color, o cambio de cobertura sin cambiar de color fuera del verde
    const d = ORDEN[f.semaforo] - ORDEN[a.semaforo] || (f.semaforo !== 'verde' ? a.cobertura - f.cobertura : 0);
    if (!d) return [];
    return [{ id: f.id, nombre: f.nombre, cambio: d > 0 ? 'empeora' : 'mejora', de: a.semaforo, a: f.semaforo, cobertura_antes: a.cobertura, cobertura_despues: f.cobertura }];
  });
}


// Propuesta de acciones (pasos 4-5): contexto para Claude y propuesta por reglas si no hay IA.
// Sin dependencias: lo usan la demo local (demo.js) y el nodo de código de n8n (exportar-n8n.js).

function contexto(r, cambios, evento, vac, datos) {
  const ids = cambios.filter(c => c.cambio === 'empeora').map(c => c.id);
  const afectadas = r.funciones.filter(x => ids.includes(x.id));
  const implicadas = new Set(afectadas.flatMap(x => x.skills.filter(s => s.semaforo !== 'verde').flatMap(s => s.personas)));
  const formaciones = new Set(afectadas.flatMap(x => x.skills.flatMap(s => s.formacion || [])));
  // Si alguna función se rediseña con IA, la recualificación sale de las formaciones de IA del catálogo
  if (afectadas.some(x => x.respuesta === 'redisenar')) datos.catalogo.filter(c => c.skill.startsWith('ia-')).forEach(c => formaciones.add(c.id));
  if (vac) {
    // Lente AI first: una skill del puesto que solo sostiene funciones a rediseñar no se cubre tal cual (ni dentro ni fuera)
    vac.perfil.forEach(p => { p.redisenar = !!p.funcion && r.funciones.find(f => f.id === p.funcion)?.respuesta === 'redisenar'; });
    vac.candidatos.forEach(c => { implicadas.add(c.id); c.brechas.forEach(b => b.formacion.forEach(x => formaciones.add(x))); });
    // Solo People: compa-ratio del candidato frente a la banda del puesto que asumiría
    const banda = datos.bandas.find(b => b.banda_id === datos.empleados.find(e => e.id === vac.id).banda_id);
    vac.candidatos.forEach(c => { c.compa_en_puesto = +(datos.empleados.find(e => e.id === c.id).salario_ficticio / banda.medio).toFixed(2); c.banda_puesto = banda.banda_id; });
  }
  return {
    evento, cambios, funciones_afectadas: afectadas, key_people: r.key_people, vacante: vac,
    senales: r.senales_rotacion.filter(s => implicadas.has(s.id)),
    catalogo: datos.catalogo.filter(c => formaciones.has(c.id)),
  };
}

// Decisión de cubrir el puesto: dos opciones excluyentes con el mismo grupo (A fuera, B el mejor candidato interno)
function opcionesVacante(ctx) {
  const v = ctx.vacante;
  if (!v || !v.perfil.some(p => p.skill !== 'liderazgo' && !p.redisenar)) return [];
  const grupo = `VAC-${v.id}`;
  const prioridad = ctx.funciones_afectadas.map(x => x.prioridad).sort()[0] || 'P1';
  const ops = [{ prioridad, funcion_id: '', tipo: 'contratar', grupo, accion: `Opción A · Buscar fuera: ${v.rol} (${v.perfil.filter(p => !p.redisenar).map(p => `${p.skill} ${p.nivel}`).join(', ')})`, empleado_id: '', skill_id: '', formacion_id: '',
    por_que: v.candidatos.length ? 'Nadie dentro cumple el perfil completo.' : 'Ningún candidato interno cumple la mitad del perfil.',
    riesgo_si_no: `Proceso de 2-3 meses; mientras tanto, ${v.equipo ? `${v.equipo} personas sin responsable` : 'sus funciones dependen de quien quede'}.` }];
  const c = v.candidatos[0];
  if (c) {
    const conForm = c.brechas.find(b => b.formacion.length);
    ops.push({ prioridad, funcion_id: c.brechas.find(b => b.funcion)?.funcion || '', tipo: 'movilidad', grupo, accion: `Opción B · Mover a ${c.nombre} (${c.rol}) a ${v.rol}`, empleado_id: c.id, skill_id: conForm?.skill || '', formacion_id: conForm?.formacion[0] || '',
      por_que: `Cumple ${c.cumple} de ${c.de} skills del puesto. Le falta: ${c.brechas.map(b => `${b.skill} ${b.tiene} → ${b.necesita}${b.formacion.length ? ` (${b.formacion[0]})` : ' (sin formación en el catálogo)'}`).join('; ')}.`,
      riesgo_si_no: c.key_person_en.length ? `Coste organizativo: ya es la única cobertura de ${c.key_person_en.join(', ')}; asumir el puesto concentra el riesgo en una persona.` : 'Coste organizativo: su puesto actual queda por cubrir.' });
  }
  return ops;
}

function propuestaPorReglas(ctx) {
  const acciones = opcionesVacante(ctx);
  const enVacante = skill => ctx.vacante?.perfil.some(p => p.skill === skill);
  for (const fn of ctx.funciones_afectadas) for (const s of fn.skills.filter(x => x.semaforo !== 'verde')) {
    const cand = (s.candidatos || []).find(c => !c.es_key_person);
    const form = ctx.catalogo.find(c => c.skill === s.skill);
    if (fn.respuesta === 'redisenar') {
      // Lente AI first: no se forma a nadie en el proceso actual; se rediseña y se recualifica
      const formIa = ctx.catalogo.find(c => c.skill === 'ia-automatizacion' && c.de === 1);
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'rediseno', accion: `Rediseñar ${fn.nombre} con IA y automatización${cand ? ` y recualificar a ${cand.nombre}` : ''}`, empleado_id: cand?.id || '', skill_id: 'ia-automatizacion', formacion_id: formIa?.id || '', por_que: `Cobertura ${s.cobertura} en ${s.skill} e impacto IA alto: formar un backup en el proceso actual es invertir en un proceso que va a cambiar.${cand?.con_interes ? ` ${cand.nombre} tiene interés declarado.` : ''}`, riesgo_si_no: `${fn.nombre} sigue dependiendo de ${s.cobertura} persona(s) y de un proceso manual.` });
      if (s.cobertura === 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'redistribuir', accion: `Cubrir ${fn.nombre} con apoyo temporal mientras dura el rediseño`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: 'Nadie cubre la skill hoy.', riesgo_si_no: 'La próxima entrega queda sin responsable.' });
    }
    else if (cand && s.cobertura > 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'backup', accion: `Plan de backup: ${cand.nombre} en ${s.skill} (${s.nivel_minimo - 1} → ${s.nivel_minimo})`, empleado_id: cand.id, skill_id: s.skill, formacion_id: form?.id || '', por_que: `Cobertura ${s.cobertura}. ${cand.nombre} está a un nivel${cand.con_interes ? ' y tiene interés declarado' : ''}.`, riesgo_si_no: `La función ${fn.nombre} depende de ${s.cobertura} persona.` });
    else if (enVacante(s.skill)) { /* la cubre la decisión de la vacante (opciones A/B) */ }
    else acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'contratar', accion: `Abrir vacante con ${s.skill} nivel ${s.nivel_minimo}`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: `Cobertura ${s.cobertura} y ningún candidato interno llega a tiempo.`, riesgo_si_no: `${fn.nombre} queda sin nadie que pueda sostenerla.` });
    if (s.cobertura === 1) {
      const kp = s.personas[0];
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'retencion', accion: `Conversación de permanencia con ${ctx.key_people.find(k => k.id === kp)?.nombre || kp}`, empleado_id: kp, skill_id: s.skill, formacion_id: '', por_que: 'Es la única cobertura de la skill.', riesgo_si_no: 'Una segunda salida deja la función sin cobertura.' });
    }
  }
  const n = ctx.cambios.filter(c => c.cambio === 'empeora').length;
  const nOpciones = acciones.filter(a => a.grupo).length;
  const v = nOpciones ? ctx.vacante : null, c = nOpciones > 1 ? v.candidatos[0] : null;
  const resumen = v
    ? `${ctx.evento}: ${n} función(es) empeoran. Primera decisión: cómo cubrir el puesto de ${v.rol}, buscando fuera (A)${c ? ` o moviendo a ${c.nombre} (B)` : ''}. Además se proponen ${acciones.length - nOpciones} acción(es) para reducir el riesgo mientras tanto. Todo queda pendiente de aprobación por People.`
    : `${ctx.evento}: ${n} función(es) empeoran. Se proponen ${acciones.length} acciones para su aprobación por People.`;
  const sen = c && ctx.senales.find(s => s.id === c.id);
  const detalle = c ? `${c.nombre}: probabilidad ${sen?.probabilidad || 'baja'} (${sen?.senales.join('; ') || 'sin señales'}). Si asume el puesto con su salario actual, su compa-ratio en la banda ${c.banda_puesto} sería ${c.compa_en_puesto}: la opción B exige revisar condiciones.` : '';
  return { acciones, resumen_direccion: resumen, detalle_people: detalle, observaciones: 'Propuesta generada por reglas (sin IA).' };
}

// Mensaje de usuario para prompts/proponer-acciones.md (mismo orden que la sección ## User del prompt)
function mensajeClaude(ctx) {
  const j = v => JSON.stringify(v, null, 1);
  return `Evento: ${ctx.evento}

Cambios en el mapa:
${j(ctx.cambios)}

Funciones afectadas (detalle del cálculo):
${j(ctx.funciones_afectadas)}

Key people tras el cambio:
${j(ctx.key_people)}

Señales de rotación (solo personas implicadas, confidencial People):
${j(ctx.senales)}

